import type { TaskRecord } from './state/model.js'

export function shouldAutoAbandonPrePrBlockedTask(
  task: Pick<TaskRecord, 'prNumber' | 'prUrl'>,
  checkpoint: 'before_validation' | 'before_draft_pr_open' | 'before_ready' | 'before_portal_submission',
): boolean {
  if (!['before_validation', 'before_draft_pr_open'].includes(checkpoint)) {
    return false
  }

  return task.prNumber == null && task.prUrl == null
}
